package com.srenterprises.controller; import com.srenterprises.dto.OrderDtos.*; import com.srenterprises.entity.*; import com.srenterprises.repository.*; import com.srenterprises.service.*; import jakarta.validation.*; import org.springframework.data.domain.*; import org.springframework.security.core.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController { final OrderService service; final OrderRepository orders; OrderController(OrderService s,OrderRepository o){service=s;orders=o;} @PostMapping public CustomerOrder create(Authentication a,@Valid @RequestBody Create c){return service.create(a.getName(),c);}@GetMapping public Page<CustomerOrder> mine(Authentication a,@RequestParam(defaultValue="0") int page){return orders.findByCustomerEmailIgnoreCase(a.getName(),PageRequest.of(page,20,Sort.by("createdAt").descending()));}@GetMapping("/{id}") public CustomerOrder one(Authentication a,@PathVariable UUID id){CustomerOrder o=orders.findById(id).orElseThrow(()->new NoSuchElementException("Order not found"));if(!o.customer.email.equalsIgnoreCase(a.getName())&&!a.getAuthorities().stream().anyMatch(x->x.getAuthority().matches("ROLE_(SUPER_ADMIN|ADMIN|STAFF)")))throw new org.springframework.security.access.AccessDeniedException("Not permitted");return o;} }
